// 2D compressible Euler + gravity (+y), Rayleigh-Taylor instability.
// Finite volume: WENO5-Z reconstruction of primitive variables, HLLC flux,
// SSP-RK3 time stepping, pointwise gravity source. OpenMP parallel.
// Usage: ./rt NX NY TEND NOUT AMP outprefix
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>
#include <omp.h>

#define NG 3
static const double GAM = 1.4, G = 1.0, LX = 0.25, LY = 1.0;
static int NX, NY, SX, SY;
static double dx, dy;
#define ID(i, j) ((size_t)(j) * SX + (i))

static inline double weno5(double a, double b, double c, double d, double e) {
    // reconstruct value at right face of cell c from a,b,c,d,e (WENO-Z)
    const double eps = 1e-40;
    double b0 = 13.0 / 12 * (a - 2 * b + c) * (a - 2 * b + c) + 0.25 * (a - 4 * b + 3 * c) * (a - 4 * b + 3 * c);
    double b1 = 13.0 / 12 * (b - 2 * c + d) * (b - 2 * c + d) + 0.25 * (b - d) * (b - d);
    double b2 = 13.0 / 12 * (c - 2 * d + e) * (c - 2 * d + e) + 0.25 * (3 * c - 4 * d + e) * (3 * c - 4 * d + e);
    double t5 = fabs(b0 - b2);
    double w0 = 0.1 * (1 + t5 / (b0 + eps)), w1 = 0.6 * (1 + t5 / (b1 + eps)), w2 = 0.3 * (1 + t5 / (b2 + eps));
    double s = w0 + w1 + w2;
    double q0 = (2 * a - 7 * b + 11 * c) / 6, q1 = (-b + 5 * c + 2 * d) / 6, q2 = (2 * c + 5 * d - e) / 6;
    return (w0 * q0 + w1 * q1 + w2 * q2) / s;
}

// HLLC flux in normal direction. prim: rho, un, ut, p
static inline void hllc(const double *L, const double *R, double *F) {
    double rl = L[0], ul = L[1], vl = L[2], pl = L[3];
    double rr = R[0], ur = R[1], vr = R[2], pr = R[3];
    double cl = sqrt(GAM * pl / rl), cr = sqrt(GAM * pr / rr);
    double El = pl / (GAM - 1) + 0.5 * rl * (ul * ul + vl * vl);
    double Er = pr / (GAM - 1) + 0.5 * rr * (ur * ur + vr * vr);
    double SL = fmin(ul - cl, ur - cr), SR = fmax(ul + cl, ur + cr);
    double SM = (pr - pl + rl * ul * (SL - ul) - rr * ur * (SR - ur)) / (rl * (SL - ul) - rr * (SR - ur));
    if (SL >= 0) {
        F[0] = rl * ul; F[1] = rl * ul * ul + pl; F[2] = rl * ul * vl; F[3] = (El + pl) * ul;
    } else if (SR <= 0) {
        F[0] = rr * ur; F[1] = rr * ur * ur + pr; F[2] = rr * ur * vr; F[3] = (Er + pr) * ur;
    } else if (SM >= 0) {
        double f = rl * (SL - ul) / (SL - SM);
        double Us[4] = {f, f * SM, f * vl, f * (El / rl + (SM - ul) * (SM + pl / (rl * (SL - ul))))};
        double Ul[4] = {rl, rl * ul, rl * vl, El};
        double Fl[4] = {rl * ul, rl * ul * ul + pl, rl * ul * vl, (El + pl) * ul};
        for (int k = 0; k < 4; k++) F[k] = Fl[k] + SL * (Us[k] - Ul[k]);
    } else {
        double f = rr * (SR - ur) / (SR - SM);
        double Us[4] = {f, f * SM, f * vr, f * (Er / rr + (SM - ur) * (SM + pr / (rr * (SR - ur))))};
        double Ur[4] = {rr, rr * ur, rr * vr, Er};
        double Fr[4] = {rr * ur, rr * ur * ur + pr, rr * ur * vr, (Er + pr) * ur};
        for (int k = 0; k < 4; k++) F[k] = Fr[k] + SR * (Us[k] - Ur[k]);
    }
}

static double *W[4]; // primitive work arrays rho,u,v,p (with ghosts)

static void to_prim(double **U) {
#pragma omp parallel for
    for (int j = NG; j < NY + NG; j++)
        for (int i = NG; i < NX + NG; i++) {
            size_t c = ID(i, j);
            double r = U[0][c], u = U[1][c] / r, v = U[2][c] / r;
            W[0][c] = r; W[1][c] = u; W[2][c] = v;
            W[3][c] = (GAM - 1) * (U[3][c] - 0.5 * r * (u * u + v * v));
        }
    // periodic x
#pragma omp parallel for
    for (int j = NG; j < NY + NG; j++)
        for (int g = 0; g < NG; g++)
            for (int k = 0; k < 4; k++) {
                W[k][ID(g, j)] = W[k][ID(NX + g, j)];
                W[k][ID(NX + NG + g, j)] = W[k][ID(NG + g, j)];
            }
    // reflective y (mirror, v -> -v)
#pragma omp parallel for
    for (int i = 0; i < SX; i++)
        for (int g = 0; g < NG; g++)
            for (int k = 0; k < 4; k++) {
                double s = (k == 2) ? -1.0 : 1.0;
                W[k][ID(i, NG - 1 - g)] = s * W[k][ID(i, NG + g)];
                W[k][ID(i, NY + NG + g)] = s * W[k][ID(i, NY + NG - 1 - g)];
            }
}

// compute dU/dt into L
static void rhs(double **U, double **L) {
    to_prim(U);
    for (int k = 0; k < 4; k++) memset(L[k], 0, sizeof(double) * SX * SY);
    // x-sweep
#pragma omp parallel for
    for (int j = NG; j < NY + NG; j++) {
        double Fp[4], Fm[4];
        for (int i = NG - 1; i < NX + NG; i++) { // face i+1/2
            double QL[4], QR[4];
            for (int k = 0; k < 4; k++) {
                const double *w = W[k] + ID(0, j);
                QL[k] = weno5(w[i - 2], w[i - 1], w[i], w[i + 1], w[i + 2]);
                QR[k] = weno5(w[i + 3], w[i + 2], w[i + 1], w[i], w[i - 1]);
            }
            double l[4] = {QL[0], QL[1], QL[2], QL[3]}, r[4] = {QR[0], QR[1], QR[2], QR[3]};
            if (l[0] < 1e-10 || l[3] < 1e-10) { for (int k = 0; k < 4; k++) l[k] = W[k][ID(i, j)]; }
            if (r[0] < 1e-10 || r[3] < 1e-10) { for (int k = 0; k < 4; k++) r[k] = W[k][ID(i + 1, j)]; }
            hllc(l, r, Fp); // order rho,u,v,p -> flux rho, rhou, rhov, E
            if (i >= NG) for (int k = 0; k < 4; k++) L[k][ID(i, j)] -= Fp[k] / dx;
            if (i + 1 < NX + NG) for (int k = 0; k < 4; k++) L[k][ID(i + 1, j)] += Fp[k] / dx;
        }
        (void)Fm;
    }
    // y-sweep
#pragma omp parallel for
    for (int i = NG; i < NX + NG; i++) {
        double F[4];
        for (int j = NG - 1; j < NY + NG; j++) { // face j+1/2
            double QL[4], QR[4];
            for (int k = 0; k < 4; k++) {
                const double *w = W[k];
                QL[k] = weno5(w[ID(i, j - 2)], w[ID(i, j - 1)], w[ID(i, j)], w[ID(i, j + 1)], w[ID(i, j + 2)]);
                QR[k] = weno5(w[ID(i, j + 3)], w[ID(i, j + 2)], w[ID(i, j + 1)], w[ID(i, j)], w[ID(i, j - 1)]);
            }
            // normal = v
            double l[4] = {QL[0], QL[2], QL[1], QL[3]}, r[4] = {QR[0], QR[2], QR[1], QR[3]};
            if (l[0] < 1e-10 || l[3] < 1e-10) { l[0] = W[0][ID(i, j)]; l[1] = W[2][ID(i, j)]; l[2] = W[1][ID(i, j)]; l[3] = W[3][ID(i, j)]; }
            if (r[0] < 1e-10 || r[3] < 1e-10) { r[0] = W[0][ID(i, j + 1)]; r[1] = W[2][ID(i, j + 1)]; r[2] = W[1][ID(i, j + 1)]; r[3] = W[3][ID(i, j + 1)]; }
            hllc(l, r, F);
            double Fy[4] = {F[0], F[2], F[1], F[3]};
            if (j >= NG) for (int k = 0; k < 4; k++) L[k][ID(i, j)] -= Fy[k] / dy;
            if (j + 1 < NY + NG) for (int k = 0; k < 4; k++) L[k][ID(i, j + 1)] += Fy[k] / dy;
        }
    }
    // gravity source (+y)
#pragma omp parallel for
    for (int j = NG; j < NY + NG; j++)
        for (int i = NG; i < NX + NG; i++) {
            size_t c = ID(i, j);
            L[2][c] += U[0][c] * G;
            L[3][c] += U[2][c] * G;
        }
}

static double maxdt(double **U, double cfl) {
    double m = 0;
#pragma omp parallel for reduction(max : m)
    for (int j = NG; j < NY + NG; j++)
        for (int i = NG; i < NX + NG; i++) {
            size_t c = ID(i, j);
            double r = U[0][c], u = U[1][c] / r, v = U[2][c] / r;
            double p = (GAM - 1) * (U[3][c] - 0.5 * r * (u * u + v * v));
            double cs = sqrt(GAM * p / r);
            double s = (fabs(u) + cs) / dx + (fabs(v) + cs) / dy;
            if (s > m) m = s;
        }
    return cfl / m;
}

static void dump(double **U, const char *pre, int n, double t) {
    char fn[512];
    sprintf(fn, "%s_%04d.bin", pre, n);
    FILE *f = fopen(fn, "wb");
    int hdr[2] = {NX, NY};
    fwrite(hdr, sizeof(int), 2, f);
    fwrite(&t, sizeof(double), 1, f);
    double *buf = malloc(sizeof(double) * NX * NY);
    for (int k = 0; k < 4; k++) {
        for (int j = 0; j < NY; j++)
            for (int i = 0; i < NX; i++) buf[(size_t)j * NX + i] = U[k][ID(i + NG, j + NG)];
        fwrite(buf, sizeof(double), (size_t)NX * NY, f);
    }
    free(buf);
    fclose(f);
}

int main(int argc, char **argv) {
    NX = atoi(argv[1]); NY = atoi(argv[2]);
    double tend = atof(argv[3]);
    int nout = atoi(argv[4]);
    double amp = atof(argv[5]);
    const char *pre = argv[6];
    double cfl = argc > 7 ? atof(argv[7]) : 0.4;
    SX = NX + 2 * NG; SY = NY + 2 * NG;
    dx = LX / NX; dy = LY / NY;
    double *U[4], *U1[4], *U2[4], *L[4];
    for (int k = 0; k < 4; k++) {
        U[k] = calloc(SX * SY, sizeof(double)); U1[k] = calloc(SX * SY, sizeof(double));
        U2[k] = calloc(SX * SY, sizeof(double)); L[k] = calloc(SX * SY, sizeof(double));
        W[k] = calloc(SX * SY, sizeof(double));
    }
    // initial condition: point values at cell centres
    for (int j = 0; j < NY; j++)
        for (int i = 0; i < NX; i++) {
            double x = (i + 0.5) * dx, y = (j + 0.5) * dy;
            double rho = 2.0 + (1.0 - 2.0) * 0.5 * (1 + tanh(50 * (y - 0.5)));
            double p = (y < 0.5) ? 2 * y + 1 : y + 1.5;
            double c = sqrt(GAM * p / rho);
            double v = -amp * c * cos(8 * M_PI * x) * pow(sin(M_PI * y), 6);
            size_t id = ID(i + NG, j + NG);
            U[0][id] = rho; U[1][id] = 0; U[2][id] = rho * v;
            U[3][id] = p / (GAM - 1) + 0.5 * rho * v * v;
        }
    double t = 0;
    int n = 0, step = 0;
    dump(U, pre, n++, t);
    double tout = tend / nout;
    double t0 = omp_get_wtime();
    while (t < tend - 1e-12) {
        double dt = maxdt(U, cfl);
        double tnext = n * tout;
        if (t + dt > tnext) dt = tnext - t;
        rhs(U, L);
        for (int k = 0; k < 4; k++)
#pragma omp parallel for
            for (size_t c = 0; c < (size_t)SX * SY; c++) U1[k][c] = U[k][c] + dt * L[k][c];
        rhs(U1, L);
        for (int k = 0; k < 4; k++)
#pragma omp parallel for
            for (size_t c = 0; c < (size_t)SX * SY; c++) U2[k][c] = 0.75 * U[k][c] + 0.25 * (U1[k][c] + dt * L[k][c]);
        rhs(U2, L);
        for (int k = 0; k < 4; k++)
#pragma omp parallel for
            for (size_t c = 0; c < (size_t)SX * SY; c++) U[k][c] = U[k][c] / 3.0 + 2.0 / 3.0 * (U2[k][c] + dt * L[k][c]);
        t += dt; step++;
        if (fabs(t - tnext) < 1e-12) {
            dump(U, pre, n++, t);
            fprintf(stderr, "%s t=%.4f step=%d dt=%.3e wall=%.1fs\n", pre, t, step, dt, omp_get_wtime() - t0);
        }
    }
    return 0;
}

