            double r = U[0][c], u = U[1][c] / r, v = U[2][c] / r;
            double p = (GAM - 1) * (U[3][c] - 0.5 * r * (u * u + v * v));
            double cs = sqrt(GAM * p / r);
            double s = (fabs(u) + cs) / dx + (fabs(v) + cs) / dy;
            if (s > m) m = s;
        }
    return cfl / m;
}

static void dump(double **U, const char *pre, int n, double t) {
    char fn[512];
    sprintf(fn, "%s_%04d.bin", pre, n);
    FILE *f = fopen(fn, "wb");
    int hdr[2] = {NX, NY};
    fwrite(hdr, sizeof(int), 2, f);
    fwrite(&t, sizeof(double), 1, f);
    double *buf = malloc(sizeof(double) * NX * NY);
    for (int k = 0; k < 4; k++) {
        for (int j = 0; j < NY; j++)
            for (int i = 0; i < NX; i++) buf[(size_t)j * NX + i] = U[k][ID(i + NG, j + NG)];
        fwrite(buf, sizeof(double), (size_t)NX * NY, f);
    }
    free(buf);
    fclose(f);
}

int main(int argc, char **argv) {
    NX = atoi(argv[1]); NY = atoi(argv[2]);
    double tend = atof(argv[3]);
    int nout = atoi(argv[4]);
    double amp = atof(argv[5]);
    const char *pre = argv[6];
    double cfl = argc > 7 ? atof(argv[7]) : 0.4;
    SX = NX + 2 * NG; SY = NY + 2 * NG;
    dx = LX / NX; dy = LY / NY;
    double *U[4], *U1[4], *U2[4], *L[4];
    for (int k = 0; k < 4; k++) {
        U[k] = calloc(SX * SY, sizeof(double)); U1[k] = calloc(SX * SY, sizeof(double));
        U2[k] = calloc(SX * SY, sizeof(double)); L[k] = calloc(SX * SY, sizeof(double));
        W[k] = calloc(SX * SY, sizeof(double));
    }
    // initial condition: point values at cell centres
    for (int j = 0; j < NY; j++)
        for (int i = 0; i < NX; i++) {
            double x = (i + 0.5) * dx, y = (j + 0.5) * dy;
            double rho = 2.0 + (1.0 - 2.0) * 0.5 * (1 + tanh(50 * (y - 0.5)));
            double p = (y < 0.5) ? 2 * y + 1 : y + 1.5;
            double c = sqrt(GAM * p / rho);
            double v = -amp * c * cos(8 * M_PI * x) * pow(sin(M_PI * y), 6);
            size_t id = ID(i + NG, j + NG);
            U[0][id] = rho; U[1][id] = 0; U[2][id] = rho * v;
            U[3][id] = p / (GAM - 1) + 0.5 * rho * v * v;
        }
    double t = 0;
    int n = 0, step = 0;
    dump(U, pre, n++, t);
    double tout = tend / nout;
    double t0 = omp_get_wtime();
    while (t < tend - 1e-12) {
        double dt = maxdt(U, cfl);
        double tnext = n * tout;
        if (t + dt > tnext) dt = tnext - t;
        rhs(U, L);
        for (int k = 0; k < 4; k++)
#pragma omp parallel for
            for (size_t c = 0; c < (size_t)SX * SY; c++) U1[k][c] = U[k][c] + dt * L[k][c];
        rhs(U1, L);
        for (int k = 0; k < 4; k++)
#pragma omp parallel for
            for (size_t c = 0; c < (size_t)SX * SY; c++) U2[k][c] = 0.75 * U[k][c] + 0.25 * (U1[k][c] + dt * L[k][c]);
        rhs(U2, L);
        for (int k = 0; k < 4; k++)
#pragma omp parallel for
            for (size_t c = 0; c < (size_t)SX * SY; c++) U[k][c] = U[k][c] / 3.0 + 2.0 / 3.0 * (U2[k][c] + dt * L[k][c]);
        t += dt; step++;
        if (fabs(t - tnext) < 1e-12) {
            dump(U, pre, n++, t);
            fprintf(stderr, "%s t=%.4f step=%d dt=%.3e wall=%.1fs\n", pre, t, step, dt, omp_get_wtime() - t0);
        }
    }
    return 0;
}

